-- Global reference data: currencies, countries (weekend days, VAT, time zone), Ramadan and Eid
-- windows per country, and observed public holidays. Readable by every signed-in user, written
-- only by migrations. The rows are generated from engine/src/maqdar_engine/synth/data/*.csv with
-- `maqdar-synth emit-reference-sql`; a pytest check keeps the two in sync.
-- Per-organization overrides, fx rates and work calendars arrive in Step 4.

create table public.currencies (
  code char(3) primary key check (code ~ '^[A-Z]{3}$'),
  name_en text not null,
  name_ar text,
  minor_units smallint not null check (minor_units between 0 and 3)
);
comment on table public.currencies is 'ISO 4217 currencies. minor_units is the number of decimals in use (KWD, BHD, OMR, JOD use 3).';

create table public.countries (
  code char(2) primary key check (code ~ '^[A-Z]{2}$'),
  name_en text not null,
  name_ar text,
  currency_code char(3) not null references public.currencies (code),
  weekend_days smallint[] not null check (weekend_days <@ array[1, 2, 3, 4, 5, 6, 7]::smallint[] and cardinality(weekend_days) between 1 and 3),
  vat_rate numeric(5, 2) not null check (vat_rate >= 0 and vat_rate < 100),
  timezone text not null,
  utc_offset_minutes smallint not null,
  holiday_coverage_from date,
  holiday_coverage_to date,
  check ((holiday_coverage_from is null) = (holiday_coverage_to is null)),
  check (holiday_coverage_to is null or holiday_coverage_to >= holiday_coverage_from)
);
comment on table public.countries is 'Countries with weekend days (ISO weekday numbers, 1 = Monday), VAT rate and time zone. holiday_coverage_* bounds the verified public_holidays rows.';
comment on column public.countries.weekend_days is 'ISO weekday numbers of the weekend: {5,6} = Friday-Saturday, {6,7} = Saturday-Sunday.';

create table public.ramadan_windows (
  country_code char(2) not null references public.countries (code),
  hijri_year smallint not null check (hijri_year between 1400 and 1600),
  ramadan_start date not null,
  ramadan_end date not null,
  eid_al_fitr date not null,
  arafat_day date not null,
  eid_al_adha date not null,
  source text not null,
  primary key (country_code, hijri_year),
  check (ramadan_end > ramadan_start),
  check (eid_al_fitr = ramadan_end + 1),
  check (eid_al_adha = arafat_day + 1)
);
comment on table public.ramadan_windows is 'Observed Gregorian dates of Ramadan, Eid al-Fitr, Arafat Day and Eid al-Adha per country (moon sighting differs by a day between countries). Hijri dates are labels only.';

create table public.public_holidays (
  id bigint generated always as identity primary key,
  country_code char(2) not null references public.countries (code),
  holiday_date date not null,
  name_en text not null,
  kind text not null check (kind in ('religious', 'national', 'ad_hoc_closure', 'weather')),
  sector text not null check (sector in ('all', 'government', 'private')),
  shifted_from date,
  source text not null,
  note text,
  unique (country_code, holiday_date, sector)
);
comment on table public.public_holidays is 'Observed public holidays and closures per country. sector = all means private-sector businesses close too; government marks public-sector-only days.';
create index public_holidays_country_date_idx on public.public_holidays (country_code, holiday_date);

do $$
declare
  t text;
begin
  foreach t in array array['currencies', 'countries', 'ramadan_windows', 'public_holidays'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('revoke insert, update, delete, truncate, references, trigger on public.%I from authenticated', t);
    execute format('create policy "signed-in users read" on public.%I for select to authenticated using (true)', t);
  end loop;
end
$$;

